// Puzzle Designer role-only generator (all four tiers). Uses only the seeded rng passed in by the engine.
// The angle is the designer's: checking a puzzle (how many solutions, which clue is needed, how many designs
// exist, how hard it played) rather than just solving it. Hints and explanations use only values already
// drawn (no rng calls). verify() recomputes every part by another route: Latin grids are generated by
// cell-by-cell backtracking and checked against all 576 Latin squares built from row permutations; magic
// squares are generated by the line-sum family and checked by searching that family or by permuting the
// free digits; code counts are generated by formulas and checked by listing every code; playtest figures
// are generated by sorting and checked by counting. All figures are made up; every rule is stated.
//
// Subtopics (tiers medium / hard / expert / expert-plus = 2 / 3 / 4 / 4 parts):
//   latin-grid     4x4 Latin squares: candidates + solution verdict; exact count + count after a clue;
//                  forced cells + the clue that makes it unique; a unique puzzle: needed clues and deletions
//   magic-square   3x3 magic squares: magic sum + blank entries; a typo in a draft; 1-9 completions
//   code-count     codes of L symbols from n: with repeats, no repeats, no equal neighbours, reversal;
//                  ring of lamps up to rotation and flipping
//   playtest       median and % solved; difficulty rating; two puzzles ranked; trimmed mean and a verdict

import { roundTo } from "../../js/lib/mathutil.js";

// ---------- helpers ----------

const f = (n) => String(+Number(n).toFixed(6));
const nearHalf = (n, d, margin = 0.1) => { const x = Math.abs(n) * 10 ** d; return Math.abs(x - Math.floor(x) - 0.5) < margin; };
const givenRows = (pairs) => pairs.map(([label, value]) => ({ label, value: +Number(value).toFixed(6) }));
const tolOf = (dp) => (dp === 0 ? 0 : Number((0.5 * 10 ** -dp).toFixed(dp + 1)));
const dpWord = (dp) => (dp === 0 ? "" : dp === 1 ? ", to 1 decimal place" : `, to ${dp} decimal places`);
const TIER_PARTS = { medium: 2, hard: 3, expert: 4, "expert-plus": 4 };
const TRY = 30000;
const tooMany = () => { throw new Error("role-puzzle-designer: no suitable draw"); };
const YN = (b) => (b ? "Yes" : "No");
const sum = (a) => a.reduce((s, x) => s + x, 0);
const range = (n) => Array.from({ length: n }, (_, i) => i);

function numPart(id, label, ask, val, dp, hint) {
  const p = { id, label, ask: `${ask}${dpWord(dp)}`, answerType: "number", answer: roundTo(val, dp), tolerance: tolOf(dp), hint };
  if (dp === 0) p.fuzzyNumber = 0;
  return p;
}
const choicePart = (rng, id, label, ask, answer, choices, hint) => ({ id, label, ask, answerType: "choice", answer, choices: rng.shuffle(choices), hint });
const yesNo = (rng, id, label, ask, ok, hint) => choicePart(rng, id, label, ask, YN(ok), ["Yes", "No"], hint);
function finish(prompt, parts, explanation, kind, params, given, hints) {
  const q = { prompt, answerType: "multi", parts, explanation, params: { kind, ...params }, hints };
  if (given && given.length) q.given = givenRows(given);
  return q;
}
const fence = (rows) => "```\n" + rows.join("\n") + "\n```";

// ---------- latin-grid ----------

const cellName = (i) => `row ${Math.floor(i / 4) + 1}, column ${(i % 4) + 1}`;
const gridRows4 = (g) => [0, 1, 2, 3].map((r) => [0, 1, 2, 3].map((c) => g[r * 4 + c] || ".").join(" "));
const latinRule = "fill every blank (`.`) with a digit from 1 to 4 so that each row and each column contains 1, 2, 3 and 4 exactly once";

// all completions by cell-by-cell backtracking (a given is checked like any other cell)
function latinSols(g, limit = Infinity) {
  const out = [], a = new Array(16).fill(0);
  const rec = (i) => {
    if (out.length >= limit) return;
    if (i === 16) { out.push(a.slice()); return; }
    const r = Math.floor(i / 4), c = i % 4;
    for (const d of g[i] ? [g[i]] : [1, 2, 3, 4]) {
      let ok = true;
      for (let k = 0; k < c && ok; k++) if (a[r * 4 + k] === d) ok = false;
      for (let k = 0; k < r && ok; k++) if (a[k * 4 + c] === d) ok = false;
      if (!ok) continue;
      a[i] = d; rec(i + 1); a[i] = 0;
    }
  };
  rec(0);
  return out;
}
let ALLG = null;
const allLatinG = () => (ALLG ??= latinSols(new Array(16).fill(0)));
const clashes = (g) => {
  for (let i = 0; i < 16; i++) for (let j = i + 1; j < 16; j++) {
    if (g[i] && g[i] === g[j] && (Math.floor(i / 4) === Math.floor(j / 4) || i % 4 === j % 4)) return true;
  }
  return false;
};
const candsOf = (g, x) => [1, 2, 3, 4].filter((d) => range(16).every((i) => i === x || !g[i] || g[i] !== d || (Math.floor(i / 4) !== Math.floor(x / 4) && i % 4 !== x % 4)));
const blanksOf = (g) => range(16).filter((i) => !g[i]);
const withCells = (g, pairs) => { const h = g.slice(); for (const [i, v] of pairs) h[i] = v; return h; };
const forcedCount = (g, sols) => blanksOf(g).filter((i) => sols.every((s) => s[i] === sols[0][i])).length;

function latinPuzzle(rng, given, mod) {
  const sq = rng.pick(allLatinG());
  const cells = rng.shuffle(range(16)).slice(0, given);
  const g = new Array(16).fill(0);
  for (const i of cells) g[i] = sq[i];
  if (mod) { const i = rng.pick(cells); g[i] = ((g[i] - 1 + rng.int(1, 3)) % 4) + 1; }
  return g;
}
const VERDICTS = ["No solution", "Exactly one solution", "More than one solution"];
const verdictOf = (n) => (n === 0 ? VERDICTS[0] : n === 1 ? VERDICTS[1] : VERDICTS[2]);

function genLatin(rng, tier) {
  const target0 = rng.int(0, 2), wantYes0 = rng.next() < 0.5;
  for (let i = 0; i < TRY; i++) {
    if (tier === "medium") {
      const target = target0, g = latinPuzzle(rng, rng.int(4, 10), target === 0);
      if (clashes(g)) continue;
      const n = latinSols(g, 2).length;
      if (Math.min(n, 2) !== target) continue;
      const x = rng.pick(blanksOf(g)), cand = candsOf(g, x);
      const parts = [
        numPart("cand", "Candidates", `How many digits could go in the blank at (${cellName(x)}), looking only at the digits already shown in its own row and column`, cand.length, 0, "Cross off every digit already shown in that cell's row and in its column; count what is left."),
        choicePart(rng, "verdict", "Solutions", "How many ways can the whole grid be completed?", verdictOf(n), VERDICTS, "Try to complete the grid: if you are forced all the way and nothing clashes there is one way; look for a choice that could go either way."),
      ];
      return finish(`A designer's mini Latin square puzzle: ${latinRule}.\n\n${fence(gridRows4(g))}\n\nA good puzzle has exactly one completion.`, parts,
        `**Candidates for (${cellName(x)}):** ${cand.join(", ") || "none"}, so **${cand.length}**.\n\n**Completions:** ${verdictOf(n)}.`,
        "pd-la1", { tier, g, x }, null, ["Start with the cell asked about, then think about the whole grid.", "Solving needs the digits each row and column still lacks."]);
    }
    if (tier === "hard") {
      const g = latinPuzzle(rng, rng.int(4, 8), false);
      const sols = latinSols(g), n = sols.length;
      if (n < 2 || n > 40) continue;
      const x = rng.pick(blanksOf(g)), cand = candsOf(g, x);
      if (!cand.length) continue;
      const d = rng.pick(cand), after = sols.filter((s) => s[x] === d).length;
      if (after === n) continue;
      const parts = [
        numPart("cand", "Candidates", `How many digits could go at (${cellName(x)}), looking only at the digits shown in its row and column`, cand.length, 0, "Cross off the digits already shown in that cell's row and column."),
        numPart("count", "Solutions", "How many different ways can the whole grid be completed", n, 0, "Count every completion, not just the first one you find; try each candidate digit in turn."),
        numPart("after", "With the clue", `The designer adds the clue ${d} at (${cellName(x)}). How many completions are there now`, after, 0, "Only the completions that have that digit in that cell survive."),
      ];
      return finish(`A designer is checking a mini Latin square puzzle: ${latinRule}.\n\n${fence(gridRows4(g))}`, parts,
        `**Candidates for (${cellName(x)}):** ${cand.join(", ")}, so **${cand.length}**.\n\n**Completions:** **${n}**.\n\n**With ${d} at (${cellName(x)}):** **${after}**.`,
        "pd-la2", { tier, g, x, d }, null, ["Local candidates first, then the whole grid.", "The clue can only remove completions, never add any."]);
    }
    if (tier === "expert") {
      const g = latinPuzzle(rng, rng.int(3, 6), false);
      const sols = latinSols(g), n = sols.length;
      if (n < 2 || n > 24) continue;
      const bl = blanksOf(g), x = rng.pick(bl), cand = candsOf(g, x);
      const opts = [];
      for (const b of bl) for (const d of [1, 2, 3, 4]) opts.push({ b, d, n: sols.filter((s) => s[b] === d).length });
      const uniq = opts.filter((o) => o.n === 1), not = opts.filter((o) => o.n !== 1);
      if (uniq.length < 1 || not.length < 3) continue;
      const right = rng.pick(uniq), wrong = rng.shuffle(not).slice(0, 3);
      const str = (o) => `${cellName(o.b)} = ${o.d}`;
      const forced = forcedCount(g, sols);
      const parts = [
        numPart("cand", "Candidates", `How many digits could go at (${cellName(x)}), looking only at the digits shown in its row and column`, cand.length, 0, "Cross off the digits already shown in that cell's row and column."),
        numPart("count", "Solutions", "How many different ways can the grid be completed", n, 0, "List the completions systematically, branching on one cell."),
        numPart("forced", "Forced cells", "How many blank cells hold the same digit in every completion", forced, 0, "Compare your completions cell by cell; a cell that never changes is forced."),
        choicePart(rng, "clue", "Clue", "Exactly one of these single extra clues would leave the puzzle with exactly one solution. Which one?", str(right), [right, ...wrong].map(str), "For each option, keep only the completions that agree with it and count them."),
      ];
      return finish(`A designer's mini Latin square puzzle is not yet fair: ${latinRule}.\n\n${fence(gridRows4(g))}`, parts,
        `**Candidates for (${cellName(x)}):** ${cand.join(", ") || "none"}, so **${cand.length}**.\n\n**Completions:** **${n}**.\n\n**Forced blank cells:** **${forced}**.\n\n**Unique clue:** ${str(right)} leaves 1 completion; the others leave ${wrong.map((o) => o.n).join(", ")}.`,
        "pd-la3", { tier, g, x, opts: [right, ...wrong].map(str) }, null, ["Everything here comes from the list of completions.", "A clue makes the puzzle unique when only one completion agrees with it."]);
    }
    // expert-plus: a unique puzzle; which clues does it really need?
    const target = rng.int(5, 8), sq = rng.pick(allLatinG()), g = sq.slice();
    let left = 16;
    for (const c of rng.shuffle(range(16))) {
      if (left <= target) break;
      g[c] = 0;
      if (latinSols(g, 2).length === 1) left--; else g[c] = sq[c];
    }
    const gv = range(16).filter((c) => g[c]), bl = blanksOf(g);
    if (gv.length < 5) continue;
    const needed = gv.filter((c) => latinSols(withCells(g, [[c, 0]]), 2).length > 1);
    const i1 = rng.pick(gv), cnt = latinSols(withCells(g, [[i1, 0]])).length;
    const pairs = [];
    for (let a = 0; a < gv.length; a++) for (let b = a + 1; b < gv.length; b++) pairs.push([gv[a], gv[b]]);
    const wantYes = wantYes0;
    const pair = rng.shuffle(pairs).find((pr) => (latinSols(withCells(g, pr.map((c) => [c, 0])), 2).length === 1) === wantYes);
    if (!pair) continue;
    const x = rng.pick(bl);
    const parts = [
      numPart("cell", "Solution cell", `What digit goes in the blank at (${cellName(x)}) in the solution`, sq[x], 0, "The puzzle has one solution; fill the forced cells one at a time."),
      numPart("count", "Without a clue", `The designer deletes the clue ${g[i1]} at (${cellName(i1)}). How many completions are there now`, cnt, 0, "Treat that cell as blank and count all the completions again."),
      numPart("needed", "Needed clues", "How many of the clues are needed, so that deleting just that one clue gives more than one solution", needed.length, 0, "Test each clue on its own: delete it and ask whether the completion stays unique."),
      yesNo(rng, "both", "Delete both?", `Can the designer delete **both** the clue at (${cellName(pair[0])}) and the clue at (${cellName(pair[1])}) and still have exactly one solution?`, wantYes, "Delete the two together and recount; two clues that are each unneeded alone can still be needed as a pair."),
    ];
    return finish(`A designer has this finished mini Latin square puzzle, which has exactly one solution: ${latinRule}.\n\n${fence(gridRows4(g))}\n\nShe wants to know which clues she could drop.`, parts,
      `**Solution cell (${cellName(x)}):** **${sq[x]}**.\n\n**Without the clue at (${cellName(i1)}):** **${cnt}** completions.\n\n**Needed clues:** ${needed.map((c) => `(${cellName(c)})`).join(", ") || "none"}, so **${needed.length}**.\n\n**Both deleted:** ${YN(wantYes)}.`,
      "pd-la4", { tier, g, x, i1, pair }, null, ["The puzzle is already unique: use that to find the solution.", "Each question is a recount with one or two clues blanked."]);
  }
  return tooMany();
}

// ---------- magic-square ----------

const LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
const magicOf = (c, a, b) => [c + a, c - a - b, c + b, c - a + b, c, c + a - b, c - b, c + a + b, c - a];
const gridRows3 = (g, w) => [0, 1, 2].map((r) => [0, 1, 2].map((c) => String(g[r * 3 + c]).padStart(w)).join(" "));
const cellName3 = (i) => `row ${Math.floor(i / 3) + 1}, column ${(i % 3) + 1}`;
const magicRule = "A **magic square** has all three rows, all three columns and both diagonals adding to the same sum **S**.";

function drawMagic(rng) {
  for (let i = 0; i < 1000; i++) {
    const c = rng.int(10, 30), a = rng.int(1, 9) * (rng.next() < 0.5 ? 1 : -1), b = rng.int(1, 9) * (rng.next() < 0.5 ? 1 : -1);
    const m = magicOf(c, a, b);
    if (new Set(m).size === 9 && m.every((x) => x >= 1)) return { m, c };
  }
  return tooMany();
}
// fill blanks (null) from the sum S by finishing any line that has exactly one blank
function propagate(cells, S) {
  const v = cells.slice();
  for (let moved = true; moved;) {
    moved = false;
    for (const L of LINES) {
      const bl = L.filter((i) => v[i] === null);
      if (bl.length === 1) { v[bl[0]] = S - sum(L.filter((i) => i !== bl[0]).map((i) => v[i])); moved = true; }
    }
  }
  return v;
}
const LETTERS = ["A", "B", "C"];

function genMagic(rng, tier) {
  for (let i = 0; i < TRY; i++) {
    if (tier === "medium" || tier === "hard") {
      const { m, c } = drawMagic(rng), nb = tier === "medium" ? 2 : 3, S = 3 * c;
      const blanks = rng.shuffle(range(9)).slice(0, nb);
      const cells = m.map((x, k) => (blanks.includes(k) ? null : x));
      if (!LINES.some((L) => L.every((k) => cells[k] !== null))) continue;
      if (propagate(cells, S).some((x) => x === null)) continue;
      const shown = cells.map((x, k) => (x === null ? LETTERS[blanks.indexOf(k)] : x));
      const pS = numPart("s", "Magic sum", "The magic sum S", S, 0, "A line with no blank shows you the sum; add it up.");
      const pick = tier === "medium" ? [0] : [0, 2];
      const ps = pick.map((k) => numPart(LETTERS[k].toLowerCase(), `Blank ${LETTERS[k]}`, `The number that goes in the blank marked ${LETTERS[k]}`, m[blanks[k]], 0, "Find a line with one blank; the missing number makes it add up to S."));
      return finish(`${magicRule} Fill the blanks (marked with letters) of this draft puzzle.\n\n${fence(gridRows3(shown, 2))}`, [pS, ...ps],
        `**Magic sum:** a complete line adds to **${S}**.\n\n${pick.map((k) => `**${LETTERS[k]}:** **${m[blanks[k]]}**`).join(", ")}.`,
        tier === "medium" ? "pd-ms1" : "pd-ms2", { tier, shown, ask: pick.map((k) => LETTERS[k]) }, null,
        ["Get S from a line that is already complete.", "Then finish lines that have only one blank."]);
    }
    if (tier === "expert") {
      const { m, c } = drawMagic(rng), S = 3 * c, t = rng.int(0, 8), e = rng.int(1, 9) * (rng.next() < 0.5 ? 1 : -1);
      const bad = m.slice(); bad[t] += e;
      if (bad[t] < 1) continue;
      const lines = LINES.filter((L) => sum(L.map((k) => bad[k])) === S).length;
      const others = rng.shuffle(range(9).filter((k) => k !== t)).slice(0, 3);
      const str = (k) => cellName3(k);
      const parts = [
        numPart("lines", "Lines that work", "How many of the 8 lines (3 rows, 3 columns, 2 diagonals) add to S", lines, 0, "Add each line in turn and compare with S."),
        choicePart(rng, "cell", "Mistyped cell", "Which cell holds the typo?", str(t), [t, ...others].map(str), "The typo lies on every line that fails, and on no line that works."),
        numPart("fix", "Correct number", "What number should be in that cell", m[t], 0, "Use any failing line through that cell: the cell should make it add to S."),
        numPart("err", "Size of the error", "By how much is the typed number wrong (always give a positive number)", Math.abs(e), 0, "Compare what is typed with what it should be."),
      ];
      return finish(`${magicRule} A designer's draft is meant to be magic with **S = ${S}**, but exactly one entry was mistyped.\n\n${fence(gridRows3(bad, 2))}`, parts,
        `**Lines that work:** **${lines}** of 8.\n\n**Typo:** the cell on all the failing lines is (${str(t)}).\n\n**Correct number:** **${m[t]}** (typed ${bad[t]}), an error of **${Math.abs(e)}**.`,
        "pd-ms3", { tier, bad, S, opts: [t, ...others].map(str) }, [["_S", S]],
        ["Check every line before deciding anything.", "A cell sits on two, three or four lines; the failing ones point at it."]);
    }
    // expert-plus: 1 to 9 once each, every line adds to 15, a few cells given
    const base = [2, 7, 6, 9, 5, 1, 4, 3, 8];
    const rot = (q) => [q[6], q[3], q[0], q[7], q[4], q[1], q[8], q[5], q[2]];
    const tr = (q) => [q[0], q[3], q[6], q[1], q[4], q[7], q[2], q[5], q[8]];
    const vars = []; let q = base;
    for (let r = 0; r < 4; r++) { vars.push(q, tr(q)); q = rot(q); }
    const v = rng.pick(vars), cells = rng.shuffle(range(9)).slice(0, rng.int(1, 2));
    const g = range(9).map((k) => (cells.includes(k) ? v[k] : 0));
    const comp = vars.filter((w) => cells.every((k) => w[k] === g[k]));
    if (comp.length < 2) continue;
    const blanks = range(9).filter((k) => !g[k]), forcedC = blanks.filter((k) => comp.every((w) => w[k] === comp[0][k]));
    if (!forcedC.length) continue;
    const y = rng.pick(forcedC), z = rng.pick(blanks), zv = rng.pick(comp)[z], after = comp.filter((w) => w[z] === zv).length;
    if (after >= comp.length) continue;
    const parts = [
      numPart("count", "Completions", "How many different ways can the grid be completed", comp.length, 0, "Place the missing digits in every legal way; each must make all the lines add to the stated sum."),
      numPart("forced", "Forced cells", "How many blank cells hold the same digit in every completion", forcedC.length, 0, "Compare the completions cell by cell."),
      numPart("cell", "A forced cell", `What number goes in the blank at (${cellName3(y)}) in every completion`, comp[0][y], 0, "That cell does not change from one completion to the next."),
      numPart("after", "With a clue", `The designer adds the clue ${zv} at (${cellName3(z)}). How many completions are there now`, after, 0, "Keep only the completions that agree with the clue."),
    ];
    return finish(`A designer's puzzle: use each number from 1 to 9 exactly once so that every row, every column and both diagonals add to **15**. Blanks are shown with \`.\`.\n\n${fence([0, 1, 2].map((r) => [0, 1, 2].map((c) => g[r * 3 + c] || ".").join(" ")))}`, parts,
      `**Completions:** **${comp.length}**.\n\n**Forced blank cells:** **${forcedC.length}**; (${cellName3(y)}) is always **${comp[0][y]}**.\n\n**With ${zv} at (${cellName3(z)}):** **${after}**.`,
      "pd-ms4", { tier, g, y, z, zv }, null, ["The middle cell and the way the sum splits help; the count comes from the whole list of completions.", "A clue keeps only some of the completions."]);
  }
  return tooMany();
}

// ---------- code-count ----------

const SYMS = "ABCDEFGH";
const symList = (n) => SYMS.slice(0, n).split("").join(", ");
const falling = (n, L) => { let r = 1; for (let k = 0; k < L; k++) r *= n - k; return r; };
const phi = (n) => { let c = 0; for (let k = 1; k <= n; k++) { let a = k, b = n; while (b) [a, b] = [b, a % b]; if (a === 1) c++; } return c; };
const necklaces = (n, L) => { let s = 0; for (let d = 1; d <= L; d++) if (L % d === 0) s += phi(d) * n ** (L / d); return s / L; };
const bracelets = (n, L) => (necklaces(n, L) + (L % 2 ? n ** ((L + 1) / 2) : ((n + 1) * n ** (L / 2)) / 2)) / 2;
const palindromes = (n, L) => n ** Math.ceil(L / 2);

const enoughPart = (rng, count, teams, wording) => yesNo(rng, "enough", "Enough?", wording, teams <= count, "Compare the number of codes you counted with the number needed; equal is enough.");
function drawTeams(rng, count, yes) {
  for (let i = 0; i < 200; i++) {
    const t = Math.max(2, Math.round(yes ? count * (0.55 + rng.next() * 0.4) : count * (1.08 + rng.next() * 0.6)));
    if (Math.abs(t - count) >= 0.05 * count && (t <= count) === yes) return t;
  }
  return null;
}

function genCount(rng, tier) {
  const wantYes = rng.next() < 0.5;
  for (let i = 0; i < TRY; i++) {
    const place = rng.pick(["buttons on an escape-room panel", "dials on a padlock", "tiles in a row on a gate"]);
    if (tier === "medium" || tier === "hard") {
      const L = rng.int(3, tier === "medium" ? 4 : 5), n = rng.int(Math.max(L, 4), 7);
      const free = n ** L, norep = falling(n, L), adj = n * (n - 1) ** (L - 1);
      const base = `A designer sets **${L} ${place}**, each set to one of **${n} symbols** (${symList(n)}). A code is the sequence of settings from left to right.`;
      const pF = numPart("free", "Any code", "How many different codes are possible if a symbol may be used more than once", free, 0, "Each position is a free choice from all the symbols; multiply the choices.");
      const pN = numPart("norep", "No repeats", "How many codes are possible if no symbol may be used twice", norep, 0, "Each position has one fewer choice than the one before it.");
      const pA = numPart("adj", "No equal neighbours", "How many codes are possible if two side-by-side positions may not show the same symbol (a symbol may return later)", adj, 0, "The first position is free; each later one avoids only the symbol next to it.");
      const given = [["_symbols", n], ["_length", L]];
      const exF = `**Any code:** ${n}^${L} = **${free}**.`, exN = `**No repeats:** ${Array.from({ length: L }, (_, k) => n - k).join(" × ")} = **${norep}**.`, exA = `**No equal neighbours:** ${n} × ${n - 1}^${L - 1} = **${adj}**.`;
      if (tier === "medium") return finish(base, [pF, pN], `${exF}\n\n${exN}`, "pd-cc1", { tier, n, L }, given, ["Count the choices position by position.", "Without repeats, a used symbol is no longer available."]);
      return finish(base, [pF, pN, pA], `${exF}\n\n${exN}\n\n${exA}`, "pd-cc2", { tier, n, L }, given, ["Count the choices position by position.", "A rule about neighbours only changes the choices after the first position."]);
    }
    if (tier === "expert") {
      const L = rng.int(4, 5), n = rng.int(Math.max(L, 3), 6);
      const free = n ** L, norep = falling(n, L), adj = n * (n - 1) ** (L - 1), rep = free - norep, rev = (free + palindromes(n, L)) / 2;
      const P = drawTeams(rng, rev, wantYes);
      if (!P) continue;
      const parts = [
        numPart("adj", "No equal neighbours", "How many codes are possible if two side-by-side positions may not show the same symbol", adj, 0, "The first position is free; each later one avoids the symbol before it."),
        numPart("repeat", "A repeat", "How many codes use at least one symbol more than once", rep, 0, "Count all the codes, then take away the codes with no repeated symbol."),
        numPart("rev", "Up to reversal", "Symbols may repeat, and a code and its reverse count as the same code. How many different codes are there", rev, 0, "Codes that read the same both ways are only counted once; the others pair up. Add the all-codes count to the number of palindromes and halve."),
        enoughPart(rng, rev, P, `The designer needs **${P}** panels, each with its own code, where a code and its reverse count as the same. Are there enough such codes?`),
      ];
      return finish(`A designer sets **${L} ${place}**, each set to one of **${n} symbols** (${symList(n)}). A code is the sequence of settings from left to right.`, parts,
        `**No equal neighbours:** ${n} × ${n - 1}^${L - 1} = **${adj}**.\n\n**At least one repeat:** ${free} − ${norep} = **${rep}**.\n\n**Up to reversal:** palindromes ${palindromes(n, L)}, so (${free} + ${palindromes(n, L)}) ÷ 2 = **${rev}**.\n\n**Enough for ${P}:** **${YN(wantYes)}**.`,
        "pd-cc3", { tier, n, L, P }, [["_symbols", n], ["_length", L], ["_panels", P]], ["Total codes, no-repeat codes and palindromes are the three building blocks.", "Reversal pairs up the codes that are not palindromes."]);
    }
    // expert-plus: a ring of lamps up to rotation and flipping
    const n = rng.int(2, 4), L = rng.int(4, 6);
    if (n ** L > 1100) continue;
    const lin = n ** L, rot = necklaces(n, L), br = bracelets(n, L);
    const P = drawTeams(rng, br, wantYes);
    if (!P) continue;
    const parts = [
      numPart("lin", "Fixed positions", "How many patterns are there if every lamp position counts as different", lin, 0, "Each lamp is a free choice of colour."),
      numPart("rot", "Up to rotation", "How many patterns are there if two patterns that turn into each other by rotating the ring count as the same", rot, 0, "Group the patterns into families that rotate into each other, and count the families (or average the patterns each rotation leaves unchanged)."),
      numPart("brace", "Rotate or flip", "How many patterns are there if rotating the ring or turning it over both count as the same", br, 0, "Flipping can merge families that rotation alone keeps apart."),
      enoughPart(rng, br, P, `The designer wants **${P}** lampshades, each with a pattern that differs from every other even if a shade is turned or flipped. Are there enough patterns?`),
    ];
    return finish(`A designer lights a circular lampshade with **${L} lamps** spaced evenly round a ring, each lamp in one of **${n} colours**.`, parts,
      `**Fixed positions:** ${n}^${L} = **${lin}**.\n\n**Up to rotation:** **${rot}**.\n\n**Up to rotation and flipping:** **${br}**.\n\n**Enough for ${P}:** **${YN(wantYes)}**.`,
      "pd-cc4", { tier, n, L, P }, [["_colours", n], ["_lamps", L], ["_shades", P]], ["Start with the count when every position is different.", "Rotation and flipping each merge patterns into families."]);
  }
  return tooMany();
}

// ---------- playtest ----------

const medianOf = (a) => { const s = a.slice().sort((x, y) => x - y); return s[(s.length - 1) / 2]; };
function drawPlay(rng, lo = 3, hi = 28) {
  const T = rng.pick([10, 20, 25]), ms = [];
  for (let m = Math.ceil(T / 2); m < T; m++) if (m % 2 === 1) ms.push(m);
  const m = rng.pick(ms), k = T - m, times = rng.shuffle(Array.from({ length: m }, () => rng.int(lo, hi)));
  const med = medianOf(times);
  return { T, k, m, times, med, rate: (m / T) * 100, rating: med + (10 * k) / T };
}
const playText = (d, name) => `${name ? `**${name}:** ` : ""}**${d.T}** testers tried it and **${d.k}** gave up without solving it. The solve times of the other **${d.m}** (minutes): ${d.times.join(", ")}.`;
const RULE_RATING = "**Difficulty rating** = median solve time (minutes, solvers only) + 0.1 × the percentage of testers who did **not** solve it.";
const FIRST = ["Puzzle A", "Puzzle B"];

function genPlay(rng, tier) {
  const wantA = rng.next() < 0.5, target = rng.int(0, 2);
  for (let i = 0; i < TRY; i++) {
    if (tier === "medium" || tier === "hard") {
      const d = drawPlay(rng);
      const pM = numPart("median", "Median time", "Median solve time of the testers who solved it (minutes)", d.med, 0, "Put the times in order; the median is the middle one.");
      const pR = numPart("rate", "Solved", "Percentage of all the testers who solved it (%)", d.rate, 0, "Solvers divided by everyone who tried, as a percentage; those who gave up still count as testers.");
      const given = [["_testers", d.T], ["_gaveup", d.k]];
      const exM = `**Median:** the middle of ${d.m} ordered times is **${d.med}** minutes.`, exR = `**Solved:** ${d.m} ÷ ${d.T} × 100 = **${f(d.rate)}%**.`;
      if (tier === "medium") return finish(`A designer playtests a new puzzle. ${playText(d)}`, [pM, pR], `${exM}\n\n${exR}`, "pd-pt1", { tier, T: d.T, times: d.times }, given, ["The median uses only the solvers' times.", "The percentage uses every tester."]);
      const pG = numPart("rating", "Difficulty rating", "Difficulty rating of the puzzle", d.rating, 1, "Median plus a tenth of the percentage who did not solve it.");
      return finish(`A designer playtests a new puzzle. ${playText(d)} ${RULE_RATING}`, [pM, pR, pG], `${exM}\n\n${exR}\n\n**Rating:** ${d.med} + 0.1 × ${f(100 - d.rate)} = **${f(roundTo(d.rating, 1))}**.`, "pd-pt2", { tier, T: d.T, times: d.times }, given, ["Median and the percentage who gave up are the two ingredients.", "The percentage who did not solve it is the whole minus the percentage who did."]);
    }
    if (tier === "expert") {
      const a = drawPlay(rng), b = drawPlay(rng);
      if (Math.abs(a.rating - b.rating) < 1 || (a.rating < b.rating) !== wantA) continue;
      const gap = Math.abs(a.rating - b.rating), first = a.rating < b.rating ? FIRST[0] : FIRST[1];
      const parts = [
        numPart("ra", "Rating of A", "Difficulty rating of Puzzle A", a.rating, 1, "Median plus a tenth of the percentage who did not solve it."),
        numPart("rb", "Rating of B", "Difficulty rating of Puzzle B", b.rating, 1, "Same method for the second puzzle."),
        numPart("gap", "Gap", "How many rating points apart they are (positive)", gap, 1, "Subtract the smaller rating from the larger."),
        choicePart(rng, "first", "Order", "Which puzzle should open the pack (the one that is easier, with the lower rating)?", first, FIRST, "A higher rating means a harder puzzle."),
      ];
      return finish(`A designer chooses the opening puzzle of a pack. ${RULE_RATING}\n\n${playText(a, "Puzzle A")}\n\n${playText(b, "Puzzle B")}`, parts,
        `**A:** ${a.med} + 0.1 × ${f(100 - a.rate)} = **${f(roundTo(a.rating, 1))}**.\n\n**B:** ${b.med} + 0.1 × ${f(100 - b.rate)} = **${f(roundTo(b.rating, 1))}**.\n\n**Gap:** **${f(roundTo(gap, 1))}**. **${first}** goes first.`,
        "pd-pt3", { tier, Ta: a.T, ta: a.times, Tb: b.T, tb: b.times, opts: FIRST }, [["_testersA", a.T], ["_gaveupA", a.k], ["_testersB", b.T], ["_gaveupB", b.k]],
        ["Rate each puzzle on its own first.", "Lower rating means easier."]);
    }
    // expert-plus: median, trimmed mean, % solved and a stated verdict rule
    const d = drawPlay(rng, rng.int(2, 8), rng.int(8, 28));
    const s = d.times.slice().sort((x, y) => x - y), trimmed = sum(s.slice(1, -1)) / (d.m - 2);
    if (nearHalf(trimmed, 1, 0.12)) continue;
    const cls = d.rate < 60 || d.med > 15 ? 2 : d.rate >= 90 && d.med <= 6 ? 0 : 1;
    if (cls !== target) continue;
    const V = ["Too easy", "About right", "Too hard"];
    const parts = [
      numPart("median", "Median time", "Median solve time of the solvers (minutes)", d.med, 0, "Put the solvers' times in order and take the middle one."),
      numPart("trim", "Trimmed mean", "Mean solve time after leaving out the fastest and the slowest solver (minutes)", trimmed, 1, "Remove one smallest and one largest time, then average what is left."),
      numPart("rate", "Solved", "Percentage of all the testers who solved it (%)", d.rate, 0, "Solvers divided by everyone who tried."),
      choicePart(rng, "verdict", "Verdict", "What does the rule say about this puzzle?", V[cls], V, "Check the 'too hard' conditions first, then the 'too easy' ones; anything else is about right."),
    ];
    return finish(`A designer reviews a puzzle's playtest. ${playText(d)}\n\nRule for this exercise: a puzzle is **too hard** if **fewer than 60%** of testers solved it **or** the median is **above 15 minutes**; it is **too easy** if **at least 90%** solved it **and** the median is **at most 6 minutes**; otherwise it is **about right**.`, parts,
      `**Median:** **${d.med}**.\n\n**Trimmed mean:** (${sum(s)} − ${s[0]} − ${s[s.length - 1]}) ÷ ${d.m - 2} = **${f(roundTo(trimmed, 1))}**.\n\n**Solved:** ${d.m} ÷ ${d.T} = **${f(d.rate)}%**.\n\n**Verdict:** **${V[cls]}**.`,
      "pd-pt4", { tier, T: d.T, times: d.times, opts: V }, [["_testers", d.T], ["_gaveup", d.k]], ["The rule needs the median and the percentage who solved it.", "The trimmed mean is a separate question about the spread."]);
  }
  return tooMany();
}

// ---------- entry ----------

export function generate({ subtopic, difficulty, rng }) {
  if (!(difficulty in TIER_PARTS)) throw new Error(`Unsupported difficulty: ${difficulty}`);
  if (subtopic === "latin-grid") return genLatin(rng, difficulty);
  if (subtopic === "magic-square") return genMagic(rng, difficulty);
  if (subtopic === "code-count") return genCount(rng, difficulty);
  if (subtopic === "playtest") return genPlay(rng, difficulty);
  throw new Error(`Unknown subtopic: ${subtopic}`);
}

// ---------- independent verification ----------

const num = (v) => (v === "" || v === null || v === undefined || typeof v === "boolean" ? NaN : Number(v));
const partNum = (answer, id) => (answer && typeof answer === "object" ? num(answer[id]) : NaN);
const partStr = (answer, id) => { const v = answer && typeof answer === "object" ? answer[id] : undefined; return v === undefined ? "" : Array.isArray(v) ? v.join(" | ") : String(v); };
const near = (cand, truth, tol) => Number.isFinite(cand) && Math.abs(cand - truth) <= tol + 1e-9;

// all 576 Latin squares from row permutations
const perms = (a) => (a.length <= 1 ? [a] : a.flatMap((x, i) => perms([...a.slice(0, i), ...a.slice(i + 1)]).map((r) => [x, ...r])));
let ALLV = null;
function allLatinV() {
  if (ALLV) return ALLV;
  const P = perms([1, 2, 3, 4]), out = [];
  const ok = (rows, r) => rows.every((q) => q.every((v, i) => v !== r[i]));
  for (const a of P) for (const b of P) if (ok([a], b)) for (const c of P) if (ok([a, b], c)) for (const d of P) if (ok([a, b, c], d)) out.push([...a, ...b, ...c, ...d]);
  return (ALLV = out);
}
const fits = (s, g) => g.every((v, i) => !v || s[i] === v);
const matchV = (g) => allLatinV().filter((s) => fits(s, g));
const optCell = (o) => { const m = /row (\d), column (\d) = (\d)/.exec(o); return m ? { b: (+m[1] - 1) * 4 + (+m[2] - 1), d: +m[3] } : null; };
const candV = (g, x) => {
  const r = Math.floor(x / 4), c = x % 4; let n = 0;
  for (let d = 1; d <= 4; d++) { let bad = false; for (let k = 0; k < 4; k++) { if (k !== c && g[r * 4 + k] === d) bad = true; if (k !== r && g[k * 4 + c] === d) bad = true; } if (!bad) n++; }
  return n;
};

// magic squares by searching the c/a/b family
function familyMatches(cells) {
  const out = [];
  for (let c = 1; c <= 50; c++) for (let a = -20; a <= 20; a++) for (let b = -20; b <= 20; b++) {
    const m = magicOf(c, a, b);
    if (m.every((x, i) => cells[i] === null || cells[i] === x)) out.push(m);
  }
  return out;
}
function magicAsk(p) {
  const cells = p.shown.map((x) => (typeof x === "number" ? x : null)), fam = familyMatches(cells), out = { s: null };
  if (fam.length < 1) return out;
  out.s = fam.every((m) => m[4] === fam[0][4]) ? 3 * fam[0][4] : null;
  for (const L of p.ask) { const k = p.shown.indexOf(L); out[L.toLowerCase()] = fam.every((m) => m[k] === fam[0][k]) ? fam[0][k] : null; }
  return out;
}
function placeInto(free, fn) { // every way to place the free digits into the blanks
  const rec = (rest, acc) => { if (!rest.length) { fn(acc); return; } for (let i = 0; i < rest.length; i++) rec([...rest.slice(0, i), ...rest.slice(i + 1)], [...acc, rest[i]]); };
  rec(free, []);
}
function completions15(g) {
  const used = g.filter(Boolean), free = [1, 2, 3, 4, 5, 6, 7, 8, 9].filter((d) => !used.includes(d)), blanks = range(9).filter((k) => !g[k]), out = [];
  placeInto(free, (acc) => {
    const q = g.slice(); blanks.forEach((k, i) => { q[k] = acc[i]; });
    if (LINES.every((L) => q[L[0]] + q[L[1]] + q[L[2]] === 15)) out.push(q);
  });
  return out;
}

// codes listed one by one
const codesOf = (n, L, keep) => {
  let c = 0; const w = new Array(L);
  for (let x = 0; x < n ** L; x++) { let y = x; for (let k = 0; k < L; k++) { w[k] = y % n; y = (y - w[k]) / n; } if (keep(w)) c++; }
  return c;
};
const distinctForms = (n, L, forms) => {
  const seen = new Set(), w = new Array(L);
  for (let x = 0; x < n ** L; x++) {
    let y = x; for (let k = 0; k < L; k++) { w[k] = y % n; y = (y - w[k]) / n; }
    seen.add(forms(w.slice()).map((q) => q.join("")).sort()[0]);
  }
  return seen.size;
};
const rotations = (w) => w.map((_, i) => [...w.slice(i), ...w.slice(0, i)]);
const withFlips = (w) => [...rotations(w), ...rotations(w.slice().reverse())];
const noEqualNeighbours = (w) => w.every((x, i) => i === 0 || x !== w[i - 1]);

// the median as the value with as many below as above (no sorting)
const medianCount = (a) => { const h = (a.length - 1) / 2; for (const x of a) { const lt = a.filter((y) => y < x).length, le = a.filter((y) => y <= x).length; if (lt <= h && h < le) return x; } return NaN; };
const ratingV = (T, times) => medianCount(times) + (0.1 * (100 * (T - times.length))) / T;

const ALT = {
  "pd-la1": (p) => ({ cand: candV(p.g, p.x), verdict: verdictOf(matchV(p.g).length) }),
  "pd-la2": (p) => ({ cand: candV(p.g, p.x), count: matchV(p.g).length, after: matchV(withCells(p.g, [[p.x, p.d]])).length }),
  "pd-la3": (p) => {
    const m = matchV(p.g), good = p.opts.filter((o) => { const c = optCell(o); return c && matchV(withCells(p.g, [[c.b, c.d]])).length === 1; });
    const forced = blanksOf(p.g).filter((i) => new Set(m.map((s) => s[i])).size === 1).length;
    return { cand: candV(p.g, p.x), count: m.length, forced, clue: good.length === 1 ? good[0] : null };
  },
  "pd-la4": (p) => {
    const gv = range(16).filter((i) => p.g[i]), sol = matchV(p.g);
    return {
      cell: sol.length === 1 ? sol[0][p.x] : null,
      count: matchV(withCells(p.g, [[p.i1, 0]])).length,
      needed: gv.filter((i) => matchV(withCells(p.g, [[i, 0]])).length > 1).length,
      both: YN(sol.length === 1 && matchV(withCells(p.g, p.pair.map((i) => [i, 0]))).length === 1),
    };
  },
  "pd-ms1": (p) => magicAsk(p),
  "pd-ms2": (p) => magicAsk(p),
  "pd-ms3": (p) => {
    const bad = p.bad, lines = LINES.filter((L) => sum(L.map((k) => bad[k])) === p.S).length, hits = [];
    for (let k = 0; k < 9; k++) for (let v = 1; v <= 200; v++) {
      const q = bad.slice(); q[k] = v;
      if (v !== bad[k] && LINES.every((L) => sum(L.map((j) => q[j])) === p.S)) hits.push([k, v]);
    }
    if (hits.length !== 1) return { lines, cell: null, fix: null, err: null };
    const [k, v] = hits[0];
    return { lines, cell: cellName3(k), fix: v, err: Math.abs(bad[k] - v) };
  },
  "pd-ms4": (p) => {
    const comp = completions15(p.g), bl = range(9).filter((k) => !p.g[k]);
    const forced = bl.filter((k) => comp.every((w) => w[k] === comp[0][k]));
    return { count: comp.length, forced: forced.length, cell: comp.length && forced.includes(p.y) ? comp[0][p.y] : null, after: comp.filter((w) => w[p.z] === p.zv).length };
  },
  "pd-cc1": (p) => ({ free: codesOf(p.n, p.L, () => true), norep: codesOf(p.n, p.L, (w) => new Set(w).size === p.L) }),
  "pd-cc2": (p) => ({ free: codesOf(p.n, p.L, () => true), norep: codesOf(p.n, p.L, (w) => new Set(w).size === p.L), adj: codesOf(p.n, p.L, noEqualNeighbours) }),
  "pd-cc3": (p) => {
    const rev = distinctForms(p.n, p.L, (w) => [w, w.slice().reverse()]);
    return { adj: codesOf(p.n, p.L, noEqualNeighbours), repeat: codesOf(p.n, p.L, (w) => new Set(w).size < p.L), rev, enough: YN(p.P <= rev) };
  },
  "pd-cc4": (p) => {
    const br = distinctForms(p.n, p.L, withFlips);
    return { lin: codesOf(p.n, p.L, () => true), rot: distinctForms(p.n, p.L, rotations), brace: br, enough: YN(p.P <= br) };
  },
  "pd-pt1": (p) => ({ median: medianCount(p.times), rate: (100 * p.times.length) / p.T }),
  "pd-pt2": (p) => ({ median: medianCount(p.times), rate: (100 * p.times.length) / p.T, rating: ratingV(p.T, p.times) }),
  "pd-pt3": (p) => { const a = ratingV(p.Ta, p.ta), b = ratingV(p.Tb, p.tb); return { ra: a, rb: b, gap: Math.abs(a - b), first: a < b ? p.opts[0] : p.opts[1] }; },
  "pd-pt4": (p) => {
    const med = medianCount(p.times), rate = (100 * p.times.length) / p.T;
    let lo = Infinity, hi = -Infinity;
    for (const t of p.times) { lo = Math.min(lo, t); hi = Math.max(hi, t); }
    const verdict = rate < 60 || med > 15 ? p.opts[2] : rate >= 90 && med <= 6 ? p.opts[0] : p.opts[1];
    return { median: med, trim: (sum(p.times) - lo - hi) / (p.times.length - 2), rate, verdict };
  },
};

const dpOf = (part) => (part.tolerance === 0 ? 0 : Math.round(-Math.log10(part.tolerance * 2)));

export function verify(question, answer) {
  const p = question && question.params;
  if (!p || !answer || typeof answer !== "object") return false;
  const alt = ALT[p.kind];
  const parts = question.parts;
  if (!alt || !Array.isArray(parts) || parts.length < 2) return false;
  let truth;
  try { truth = alt(p); } catch { return false; }
  for (const part of parts) {
    const tv = truth[part.id];
    if (tv === undefined || tv === null) return false;
    if (part.answerType === "number") {
      const dp = dpOf(part);
      if (!near(partNum(answer, part.id), roundTo(tv, dp), tolOf(dp))) return false;
    } else if (partStr(answer, part.id) !== tv) return false;
  }
  return true;
}
